create table `email_logs` (`id` bigint unsigned not null auto_increment primary key, `user_id` bigint unsigned null, `subject` varchar(255) not null, `to` varchar(255) not null, `body` longtext not null, `sent_at` timestamp null, `status` varchar(255) not null default 'pending', `error` text null, `job_uuid` varchar(255) null, `created_at` timestamp null, `updated_at` timestamp null) default character set {{charset}} collate {{collation}};
alter table `email_logs` add constraint `email_logs_user_id_foreign` foreign key (`user_id`) references `users` (`id`) on delete set null;
